[CmdletBinding()]param([ValidateSet('all','no-install','clean')][string]$Mode='all')
$ErrorActionPreference='Continue'; $Root=Split-Path -Parent $PSScriptRoot; $fail=0
if($Mode -ne 'no-install'){ & (Join-Path $PSScriptRoot 'install-deps.ps1'); if($LASTEXITCODE -ne 0){$fail++} }
$skip='\\(\.git|node_modules|target|build|bin|obj|\.venv)\\'; $files=Get-ChildItem $Root -Recurse -File | Where-Object {$_.FullName -notmatch $skip}
$dirs=$files | Where-Object {$_.Name -in @('package.json','pyproject.toml','requirements.txt','Cargo.toml','go.mod','pom.xml','build.gradle','build.gradle.kts','CMakeLists.txt','Package.swift','pubspec.yaml','composer.json','Gemfile')} | Select-Object -ExpandProperty DirectoryName -Unique
function S($cmd,[string[]]$args,$d){Push-Location $d; try{& $cmd @args; if($LASTEXITCODE -ne 0){$script:fail++}}catch{$script:fail++}finally{Pop-Location}}
foreach($d in $dirs){if(Test-Path "$d\package.json"){if(Test-Path "$d\package-lock.json"){S npm @('ci') $d}else{S npm @('install') $d};S npm @('run','build','--if-present') $d;S npm @('test','--if-present') $d};if(Test-Path "$d\pyproject.toml"){S python @('-m','pip','install','-e','.') $d;S python @('-m','pytest') $d};if(Test-Path "$d\requirements.txt"){S python @('-m','pip','install','-r','requirements.txt') $d};if(Test-Path "$d\Cargo.toml"){S cargo @('build','--workspace') $d;S cargo @('test','--workspace') $d};if(Test-Path "$d\go.mod"){S go @('build','./...') $d;S go @('test','./...') $d};if(Test-Path "$d\pom.xml"){S mvn @('-B','test','package') $d};if((Test-Path "$d\build.gradle") -or (Test-Path "$d\build.gradle.kts")){S gradle @('build') $d};if(Test-Path "$d\CMakeLists.txt"){S cmake @('-S','.','-B','build') $d;S cmake @('--build','build','--parallel') $d};if(Test-Path "$d\Package.swift"){S swift @('build') $d;S swift @('test') $d};if(Test-Path "$d\pubspec.yaml"){S dart @('pub','get') $d;S dart @('test') $d};if(Test-Path "$d\composer.json"){S composer @('install','--no-interaction','--prefer-dist') $d};if(Test-Path "$d\Gemfile"){S bundle @('install') $d;S bundle @('exec','rake') $d}}
Write-Host "Build complete; failures=$fail"; exit $fail
